package com.mandu.liquiddialer
import com.mandu.liquiddialer.data.*
import org.junit.Test
import org.junit.Assert.*
@org.junit.runner.RunWith(org.robolectric.RobolectricTestRunner::class)
@org.robolectric.annotation.Config(sdk=[34])
class CanvasLayoutTest {
 private fun line(x:Int,y:Int,w:Int=1000,h:Int=1000)=CallCanvas.Stroke(2,3,listOf(CallCanvas.Point(x,y),CallCanvas.Point(x+w,y+h)))
 private val rows=listOf(line(1000,1000),line(3500,4000),line(7000,6500))
 private fun apply(e:CanvasLayout.Edit,ss:List<CallCanvas.Stroke> = rows,selection:Set<Int> = ss.indices.toSet())=CanvasLayout.apply(ss,selection,e)
 @Test fun alignLeftRightAndSelectionBounds(){assertEquals(listOf(1000,1000,1000),apply(CanvasLayout.Edit.LEFT).map{CanvasLayout.bounds(it).left});assertEquals(listOf(8000,8000,8000),apply(CanvasLayout.Edit.RIGHT).map{CanvasLayout.bounds(it).right})}
 @Test fun alignTopBottom(){assertEquals(listOf(1000,1000,1000),apply(CanvasLayout.Edit.TOP).map{CanvasLayout.bounds(it).top});assertEquals(listOf(7500,7500,7500),apply(CanvasLayout.Edit.BOTTOM).map{CanvasLayout.bounds(it).bottom})}
 @Test fun alignCentersUsesGroupBounds(){val x=apply(CanvasLayout.Edit.CENTER_X);assertTrue(x.all{CanvasLayout.bounds(it).centerX==4500.0});val y=apply(CanvasLayout.Edit.CENTER_Y);assertTrue(y.all{CanvasLayout.bounds(it).centerY==4250.0})}
 @Test fun spacingCentersKeepsEndpointsAndStableOrder(){val n=apply(CanvasLayout.Edit.SPACE_X);assertEquals(rows.first(),n.first());assertEquals(rows.last(),n.last());assertEquals(4500.0,CanvasLayout.bounds(n[1]).centerX,0.0);assertEquals(listOf(1500.0,4500.0,7500.0),n.map{CanvasLayout.bounds(it).centerX})}
 @Test fun verticalSpacingAndUnsortedInput(){val s=listOf(rows[2],rows[0],rows[1]);val n=apply(CanvasLayout.Edit.SPACE_Y,s);assertEquals(s[0],n[0]);assertEquals(s[1],n[1]);assertEquals(4250.0,CanvasLayout.bounds(n[2]).centerY,0.0)}
 @Test fun spacingMeansCentersNotGaps(){val s=listOf(line(500,1000,500),line(3500,3000,2000),line(8000,5000,1500));val n=apply(CanvasLayout.Edit.SPACE_X,s);val c=n.map{CanvasLayout.bounds(it).centerX};assertEquals(c[1]-c[0],c[2]-c[1],1.0);assertNotEquals(CanvasLayout.bounds(n[1]).left-CanvasLayout.bounds(n[0]).right,CanvasLayout.bounds(n[2]).left-CanvasLayout.bounds(n[1]).right)}
 @Test fun nudgeAllFourDirectionsExactlyTwoPercent(){val ss=listOf(rows[0]);for((e,d)in listOf(CanvasLayout.Edit.NUDGE_LEFT to(-200 to 0),CanvasLayout.Edit.NUDGE_RIGHT to(200 to 0),CanvasLayout.Edit.NUDGE_UP to(0 to -200),CanvasLayout.Edit.NUDGE_DOWN to(0 to 200))){val n=apply(e,ss).single();assertEquals(ss[0].points.map{CallCanvas.Point(it.x+d.first,it.y+d.second)},n.points)}}
 @Test fun wholeNudgeRefusedAtEdgeNotClamped(){val ss=listOf(line(0,1000),line(3000,3000));assertTrue(runCatching{apply(CanvasLayout.Edit.NUDGE_LEFT,ss)}.isFailure);assertEquals(0,ss.first().points.first().x)}
 @Test fun unselectedInkUnchangedAndStyleGeometryPreserved(){for(e in CanvasLayout.Edit.entries){val next=if(e==CanvasLayout.Edit.SPACE_X||e==CanvasLayout.Edit.SPACE_Y)apply(e)else apply(e,rows,setOf(0,2));if(e!=CanvasLayout.Edit.SPACE_X&&e!=CanvasLayout.Edit.SPACE_Y)assertEquals(rows[1],next[1]);rows.zip(next).forEach{(a,b)->assertEquals(a.ink,b.ink);assertEquals(a.width,b.width);assertEquals(a.points.size,b.points.size);val dx=b.points.first().x-a.points.first().x;val dy=b.points.first().y-a.points.first().y;assertTrue(a.points.zip(b.points).all{(p,q)->q.x-p.x==dx&&q.y-p.y==dy})}}}
 @Test fun selectionAndMinimumCountsValidated(){for(s in listOf(emptySet(),setOf(-1),setOf(3)))assertTrue(runCatching{apply(CanvasLayout.Edit.LEFT,rows,s)}.isFailure);assertTrue(runCatching{apply(CanvasLayout.Edit.LEFT,rows,setOf(0))}.isFailure);assertTrue(runCatching{apply(CanvasLayout.Edit.SPACE_Y,rows,setOf(0,1))}.isFailure)}
 @Test fun noOpAndTiedCentersDoNotInventHistory(){val same=listOf(line(1000,1000),line(1000,3000),line(1000,5000));val d=CanvasLayout.Draft(same);assertFalse(d.change(apply(CanvasLayout.Edit.SPACE_X,same)));assertFalse(d.canUndo);assertEquals(same,apply(CanvasLayout.Edit.LEFT,same))}
 @Test fun dotsAndClosedShapesPreserveGeometry(){val s=listOf(CallCanvas.Stroke(0,1,listOf(CallCanvas.Point(2500,2500))),CallCanvas.Stroke(1,2,listOf(CallCanvas.Point(4000,3000),CallCanvas.Point(6000,3000),CallCanvas.Point(4000,3000))));val n=apply(CanvasLayout.Edit.LEFT,s);assertEquals(1,n.first().points.size);assertEquals(n[1].points.first(),n[1].points.last())}
 @Test fun roundingWithinOneCoordinateAndEqualTranslations(){val ss=listOf(line(1001,1000,1001),line(4000,3000,1000),line(7000,5000,1000));val n=apply(CanvasLayout.Edit.CENTER_X,ss);val c=n.map{CanvasLayout.bounds(it).centerX};assertTrue(c.max()-c.min()<=1.0)}
 @Test fun undoRedoAtomicAndNewEditClearsRedo(){val d=CanvasLayout.Draft(rows);val a=apply(CanvasLayout.Edit.LEFT);d.change(a);assertTrue(d.canUndo);d.undo();assertEquals(rows,d.rows);d.redo();assertEquals(a,d.rows);d.undo();d.change(apply(CanvasLayout.Edit.TOP));assertFalse(d.canRedo)}
 @Test fun historyLimitedToFortyNoInitialDestructiveUndo(){val d=CanvasLayout.Draft(rows);assertFalse(d.canUndo);repeat(45){d.change(CanvasLayout.apply(d.rows,setOf(0),if(it%2==0)CanvasLayout.Edit.NUDGE_RIGHT else CanvasLayout.Edit.NUDGE_LEFT))};repeat(45){d.undo()};assertEquals(rows[0].points.first().x+200,d.rows[0].points.first().x);repeat(40){d.redo()};assertEquals(rows[0].points.first().x+200,d.rows[0].points.first().x)}
 @Test fun serializeKeepsExistingFormat(){val n=apply(CanvasLayout.Edit.BOTTOM);assertEquals(n,CallCanvas.decode(CallCanvas.encode(mapOf("+919876543210" to n))).values.single())}
 @Test fun rejectsDifferentStrokeCountOrInvalidInk(){val d=CanvasLayout.Draft(rows);assertTrue(runCatching{d.change(rows.drop(1))}.isFailure);assertTrue(runCatching{d.change(rows.map{it.copy(ink=10)})}.isFailure);assertEquals(rows,d.rows);assertFalse(d.canUndo)}
 @Test fun staleAndCorruptSavePreserveFilesAndOtherNumbers(){val ctx=androidx.test.core.app.ApplicationProvider.getApplicationContext<LdApp>();val f=java.io.File(ctx.filesDir,"call_canvas.json");f.delete();java.io.File(f.path+".bak").delete();val a=CallCanvas.save(ctx,"+919876543210","",rows);val b=CallCanvas.save(ctx,"+441234567890",a.raw,listOf(rows[0]));assertTrue(runCatching{CallCanvas.save(ctx,"+919876543210",a.raw,apply(CanvasLayout.Edit.LEFT))}.isFailure);assertEquals(b.raw,f.readText());assertEquals(listOf(rows[0]),CallCanvas.read(ctx,"+441234567890").strokes);f.writeText("broken");assertTrue(runCatching{CallCanvas.save(ctx,"+919876543210",b.raw,rows)}.isFailure);assertEquals("broken",f.readText())}
}
